parameters.jsCode:
const shotRows = $input.first().json.rows;
const projectId = shotRows[0].project_id;

let characters = [];
try {
  characters = $('Load Characters').item.json.rows || [];
} catch (e) {
  characters = [];
}

const characterMap = {};
for (const c of characters) {
  characterMap[c.name] = {
    character_id: c.character_id,
    voice_profile: c.voice_profile || 'narrator',
    description: c.description
  };
}

const narrationShots = shotRows.map(row => ({
  shot_id: row.shot_id,
  shot_number: row.shot_number,
  scene_id: row.scene_id,
  scene_number: row.scene_number,
  description: row.description,
  duration_seconds: row.duration_seconds,
  characters_present: JSON.parse(row.characters_present || '[]'),
  emotional_tone: row.emotional_tone,
  dialogue_in_shot: row.dialogue_in_shot
}));

const batchSize = 10;
const batches = [];
for (let i = 0; i < narrationShots.length; i += batchSize) {
  batches.push(narrationShots.slice(i, i + batchSize));
}

return [{
  json: {
    project_id: projectId,
    title: shotRows[0].title,
    language: shotRows[0].language,
    narration_shots: narrationShots,
    character_map: characterMap,
    total_shots: narrationShots.length,
    batches: batches,
    total_batches: batches.length
  }
}];

parameters.jsonBody:
={
  "model": "{{ $env.OLLAMA_MODEL || 'llama3' }}",
  "prompt": "You are a voice and narration director. Assign voices and generate narration text for each shot.

Project: '{{ $('Execute Logic').item.json.title }}'
Character profiles: {{ JSON.stringify($('Execute Logic').item.json.character_map) }}

Shots batch: {{ JSON.stringify($('Execute Logic').item.json.batches[0]) }}

For each shot, generate:
1. narration_text: the text to be spoken by TTS
2. voice_id: which voice profile to use (character name or narrator)
3. voice_params: {speed: 0.8-1.2, pitch: -2 to 2, emotion: string}
4. narration_type: {narration, dialogue, internal_monologue}
5. priority: {high, medium, low}
6. estimated_audio_duration: seconds

Return as JSON array with shot_id as key.",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const responseText = $input.first().json.response || '{}';
let voiceData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    voiceData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      voiceData = Object.entries(parsed).map(([key, val]) => ({ shot_id: key, ...val }));
    }
  }
} catch (e) {
  voiceData = [];
}

const projectId = $('Execute Logic').item.json.project_id;

const audioJobs = [];
let totalNarrations = 0;

for (const vd of voiceData) {
  totalNarrations++;
  audioJobs.push({
    json: {
      job_type: 'tts_generation',
      shot_id: vd.shot_id,
      project_id: projectId,
      narration_text: vd.narration_text || '',
      voice_id: vd.voice_id || 'narrator',
      voice_params: JSON.stringify(vd.voice_params || {}),
      narration_type: vd.narration_type || 'narration',
      priority: vd.priority || 'medium',
      estimated_audio_duration: vd.estimated_audio_duration || 5,
      state: 'pending'
    }
  });
}

return [{
  json: {
    project_id: projectId,
    audio_jobs: audioJobs,
    total_narrations: totalNarrations
  }
}];

